<?php $this->assign('title', 'Movimentar estoque'); ?><h1 class="h3 mb-4">Movimentar estoque</h1><div class="card border-0 shadow-sm"><div class="card-body p-4"><?= $this->Form->create() ?><div class="alert alert-info">Selecione medicamento e lote, ou somente um produto. O razão não poderá ser alterado ou excluído.</div><div class="row g-3"><div class="col-md-4"><?= $this->Form->control('medicamento_id', ['options' => $medicamentos, 'empty' => 'Nenhum medicamento', 'class' => 'form-select']) ?></div><div class="col-md-4"><?= $this->Form->control('lote_id', ['options' => $lotes, 'empty' => 'Nenhum lote', 'class' => 'form-select']) ?></div><div class="col-md-4"><?= $this->Form->control('produto_id', ['options' => $produtos, 'empty' => 'Nenhum produto', 'class' => 'form-select']) ?></div><div class="col-md-4"><?= $this->Form->control('tipo', ['options' => ['entrada_manual' => 'Entrada manual', 'saida_manual' => 'Saída manual', 'ajuste_positivo' => 'Ajuste positivo', 'ajuste_negativo' => 'Ajuste negativo', 'transferencia' => 'Transferência', 'devolucao' => 'Devolução', 'avaria' => 'Avaria', 'perda' => 'Perda', 'vencimento' => 'Vencimento', 'inventario' => 'Inventário'], 'class' => 'form-select']) ?></div><div class="col-md-4"><?= $this->Form->control('quantidade', ['type' => 'number', 'step' => '0.001', 'min' => '0.001', 'class' => 'form-control']) ?></div><div class="col-md-4"><?= $this->Form->control('motivo', ['class' => 'form-control']) ?></div><div class="col-12"><?= $this->Form->control('observacao', ['class' => 'form-control']) ?></div></div><div class="mt-4"><?= $this->Form->button('Registrar', ['class' => 'btn btn-primary']) ?> <?= $this->Html->link('Cancelar', ['action' => 'index'], ['class' => 'btn btn-outline-secondary']) ?></div><?= $this->Form->end() ?></div></div>
